  /**
   * Reopen the asking conversation so the MCP server a person approved reaches it, with the words
   * that say so going in as it starts. A start already under way may have read the servers before
   * this one was registered, so once it has arrived it is reopened like any running conversation
   * ({@link reopenWhenItsToolsMoved}). One that is not running is started by the words, and a start
   * reads the servers. Answers false when the words could not be kept; while a start under way is
   * waited for they are in memory only, and the answer is true.
   */
  private reopenForItsTools(conversation: string, told: ItsToolsMoved): boolean {
    const starting = this.slots.get(conversation)
    if (starting !== undefined && starting.session === null && !onItsWayOut(starting)) {
      const again = (): void => {
        try {
          // A start that never registered is not waited for again: the words are held for the next.
          const neverRegistered =
            this.slots.get(conversation) === starting && starting.session === null
          if (neverRegistered) this.tellTheAsker(conversation, told.reopened)
          else this.reopenForItsTools(conversation, told)
        } catch (error) {
          console.warn(
            `runtime host could not reopen ${conversation} with its new tools: ${errorMessage(error)}`,
          )
        }
      }
      void starting.arrived.then(again, again)
      return true
    }
    const session = this.slots.get(conversation)?.session ?? null
    if (session === null || !this.runsNow(conversation) || this.keptStopped(conversation)) {
      return this.tellTheAsker(conversation, told.reopened)
    }
    session.itsToolsMoved = [...(session.itsToolsMoved ?? []), told]
    this.reopenWhenItsToolsMoved(session)
    return true
  }

  /**
   * Reopen a running conversation for the tools a person approved, once nothing would be lost
   * ({@link whatAReopenWaitsFor}): asked now, again as each turn ends ({@link flushQueued}), and as a
   * card ends ({@link aCardMayHaveEnded}). Its turn, a card it waits on — by its status, or open in
   * its record ({@link aCardIsOpenIn}) — or the continuation of a turn the app cut, is let finish
   * first. While its turn runs, what arrives meanwhile waits, since the end of the turn reopens it
   * before anything held goes in; while only a card open in its record holds it, what arrives goes
   * in as a turn, and the reopen is asked again at that turn's end. Background work or planning is
   * never ended for this: the conversation is told now that it was not reopened, and gets the tools
   * at its next start. A stop meanwhile hands the words on with what it held
   * ({@link handOnWhatItHeld}).
   *
   * Answers whether a reopen is under way, so a flush leaves what is held for the start.
   */
  private reopenWhenItsToolsMoved(session: HostedSession): boolean {
    if (session.reopeningForItsTools === true) return true
    const told = session.itsToolsMoved
    if (told === undefined) return false
    if (
      this.launches.closed ||
      this.itStoppedUnder(session) ||
      session.reopeningOnTheCurrentSignIn === true
    ) {
      // Already stopping: the words go with what it holds, and its next start reads the servers.
      delete session.itsToolsMoved
      for (const one of told) {
        this.holdUntilItStarts(session.id, one.reopened, TOLD_ABOUT_A_SERVER_REQUEST)
      }
      return false
    }
    const cutTurnWaits =
      this.cutHoldsTheFirstBatch.has(session.id) ||
      this.continuationLife.get(session.id) === session
    const waits = cutTurnWaits
      ? 'its-turn'
      : (this.whatAReopenWaitsFor(session) ?? (this.aCardIsOpenIn(session) ? 'a-person' : null))
    if (waits === 'its-turn' || waits === 'a-person') return false
    if (waits !== null) {
      delete session.itsToolsMoved
      for (const one of told) this.tellTheAsker(session.id, one.notReopened(waits))
      return false
    }
    let closing: Promise<void>
    try {
      closing = this.close(session.id, THE_APP_ITSELF)
    } catch (error) {
      console.warn(
        `runtime host could not stop ${session.id} to reopen it with its new tools: ${errorMessage(error)}`,
      )
      return false
    }
    // Closing now, so nothing else goes in: the words are held for the start the stop makes for
    // them, and the flush this hold asks for leaves them, since the reopen is under way.
    delete session.itsToolsMoved
    session.reopeningForItsTools = true
    this.reopeningForApprovedTools.add(session.id)
    for (const one of told) {
      this.holdUntilItStarts(session.id, one.reopened, TOLD_ABOUT_A_SERVER_REQUEST)
    }
    console.info(
      `runtime host: reopening ${session.id} so an MCP server a person approved reaches it`,
    )
    void closing.catch((error: unknown) => {
      // No stop, so no reopen of its own follows it.
      this.reopeningForApprovedTools.delete(session.id)
      console.warn(
        `runtime host could not stop ${session.id} to reopen it with its new tools: ${errorMessage(error)}`,
      )
    })
    return true
  }

  /**
   * Whether a card the provider raised in this life of the conversation is still open in its
   * record. The provider's status shows a card it holds; this also counts one its record still
   * holds open, which the person may be reading. A question this app asked for the agent is not
   * one: it outlives a reopen. Only a complete reading says there is none: a row these reads could
   * not read, or a record that cannot be read at all, is taken as holding one.
   */
  private aCardIsOpenIn(session: HostedSession): boolean {
    const unread = rowsUnreadOnce()
    try {
      const open = this.deps.store
        .routedRequestsOf(session.id, unread)
        .filter((one) => REQUEST_IS_OPEN[one.state] && one.at >= session.lifeSince)
      if (open.length > 0) {
        const asked = this.deps.store.questionsRaisedIn(session.id, unread)
        if (open.some((one) => asked.get(one.requestId)?.raisedBy !== 'this-app')) return true
      }
      return unread.count > 0 || unread.ledgersSkipped > 0
    } catch (error) {
      console.warn(
        `runtime host could not read ${session.id}'s open cards, so its reopen waits: ${errorMessage(error)}`,
      )
      return true
    }
  }

  /**
   * A row that can open or end a card was written: a reopen for its tools that waits is asked again,
   * once this stretch has written it ({@link reopenWhenItsToolsMoved}).
   */
  private aCardMayHaveEnded(conversation: string): void {
    const live = this.slots.get(conversation)?.session ?? null
    if (live === null || live.itsToolsMoved === undefined) return
    queueMicrotask(() => {
      try {
        this.reopenWhenItsToolsMoved(live)
      } catch (error) {
        console.warn(
          `runtime host could not reopen ${conversation} with its new tools: ${errorMessage(error)}`,
        )
      }
    })
  }

